// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// 本域进程存活
	// (GET /healthz)
	Health(ctx context.Context, request HealthRequestObject) (HealthResponseObject, error)
	// 本域启动/恢复就绪
	// (GET /readyz)
	Ready(ctx context.Context, request ReadyRequestObject) (ReadyResponseObject, error)
	// 取得可恢复的数据屏障
	// (POST /v1/barriers)
	AcquireBarrier(ctx context.Context, request AcquireBarrierRequestObject) (AcquireBarrierResponseObject, error)
	// 释放屏障
	// (DELETE /v1/barriers/{barrierId})
	ReleaseBarrier(ctx context.Context, request ReleaseBarrierRequestObject) (ReleaseBarrierResponseObject, error)
	// 文档及回收站分页列表
	// (GET /v1/documents)
	ListDocuments(ctx context.Context, request ListDocumentsRequestObject) (ListDocumentsResponseObject, error)
	// 新建共享草稿文档
	// (POST /v1/documents)
	CreateDocument(ctx context.Context, request CreateDocumentRequestObject) (CreateDocumentResponseObject, error)
	// 读取全篇共享草稿及编辑状态
	// (GET /v1/documents/{documentId}/draft)
	ReadDraft(ctx context.Context, request ReadDraftRequestObject) (ReadDraftResponseObject, error)
	// 自动保存完整Tiptap正文
	// (PUT /v1/documents/{documentId}/draft)
	SaveDraft(ctx context.Context, request SaveDraftRequestObject) (SaveDraftResponseObject, error)
	// 查看署名发布/git版本历史
	// (GET /v1/documents/{documentId}/history)
	ReadRevisionHistory(ctx context.Context, request ReadRevisionHistoryRequestObject) (ReadRevisionHistoryResponseObject, error)
	// 查看某次发布的正文
	// (GET /v1/documents/{documentId}/history/{historyId})
	ReadHistoricalRevision(ctx context.Context, request ReadHistoricalRevisionRequestObject) (ReadHistoricalRevisionResponseObject, error)
	// 按稳定块ID对比历史版本
	// (POST /v1/documents/{documentId}/history:diff)
	DiffRevisions(ctx context.Context, request DiffRevisionsRequestObject) (DiffRevisionsResponseObject, error)
	// 回滚历史形成新发布/git提交
	// (POST /v1/documents/{documentId}/history:rollback)
	RollbackPublishedRevision(ctx context.Context, request RollbackPublishedRevisionRequestObject) (RollbackPublishedRevisionResponseObject, error)
	// 关闭页面释放自身锁
	// (DELETE /v1/documents/{documentId}/lock)
	ReleaseEditLock(ctx context.Context, request ReleaseEditLockRequestObject) (ReleaseEditLockResponseObject, error)
	// 打开文档自动获得内存编辑锁
	// (POST /v1/documents/{documentId}/lock)
	AcquireEditLock(ctx context.Context, request AcquireEditLockRequestObject) (AcquireEditLockResponseObject, error)
	// 心跳维持锁并处理长时间无输入
	// (PUT /v1/documents/{documentId}/lock)
	RenewEditLock(ctx context.Context, request RenewEditLockRequestObject) (RenewEditLockResponseObject, error)
	// 只有超管强制释放别人锁
	// (POST /v1/documents/{documentId}/lock:force-release)
	ForceReleaseEditLock(ctx context.Context, request ForceReleaseEditLockRequestObject) (ForceReleaseEditLockResponseObject, error)
	// 修改标题/路径/SEO描述/分享图
	// (PUT /v1/documents/{documentId}/metadata)
	UpdateDocumentMetadata(ctx context.Context, request UpdateDocumentMetadataRequestObject) (UpdateDocumentMetadataResponseObject, error)
	// 获取仍公开的精确正文快照
	// (GET /v1/documents/{documentId}/published)
	ReadPublishedRevision(ctx context.Context, request ReadPublishedRevisionRequestObject) (ReadPublishedRevisionResponseObject, error)
	// 点击发布才公开精确共享草稿版本
	// (POST /v1/documents/{documentId}:publish)
	PublishDocument(ctx context.Context, request PublishDocumentRequestObject) (PublishDocumentResponseObject, error)
	// 从回收站恢复为草稿
	// (POST /v1/documents/{documentId}:restore)
	RestoreDocument(ctx context.Context, request RestoreDocumentRequestObject) (RestoreDocumentResponseObject, error)
	// 首次发布前请模型建议英文路径名和搜索摘要
	// (POST /v1/documents/{documentId}:suggest-publication)
	SuggestPublicationMetadata(ctx context.Context, request SuggestPublicationMetadataRequestObject) (SuggestPublicationMetadataResponseObject, error)
	// 删除进回收站，可选旧URL替代跳转
	// (POST /v1/documents/{documentId}:trash)
	TrashDocument(ctx context.Context, request TrashDocumentRequestObject) (TrashDocumentResponseObject, error)
	// 撤回后回草稿并让公开页面下线
	// (POST /v1/documents/{documentId}:withdraw)
	WithdrawDocument(ctx context.Context, request WithdrawDocumentRequestObject) (WithdrawDocumentResponseObject, error)
	// 经对象API读取私有文件而不共享目录
	// (GET /v1/objects/{objectId})
	ReadContentObject(ctx context.Context, request ReadContentObjectRequestObject) (ReadContentObjectResponseObject, error)
	// 管理员预览草稿公开样式
	// (POST /v1/previews)
	CreatePreviewGrant(ctx context.Context, request CreatePreviewGrantRequestObject) (CreatePreviewGrantResponseObject, error)
	// 只向对应管理员验证草稿预览
	// (POST /v1/previews:validate)
	ValidatePreviewGrant(ctx context.Context, request ValidatePreviewGrantRequestObject) (ValidatePreviewGrantResponseObject, error)
	// 解析301/410公开路径
	// (GET /v1/public-path:resolve)
	ResolvePublicPath(ctx context.Context, request ResolvePublicPathRequestObject) (ResolvePublicPathResponseObject, error)
	// 读取公开导航
	// (GET /v1/public-tree)
	ReadPublicTree(ctx context.Context, request ReadPublicTreeRequestObject) (ReadPublicTreeResponseObject, error)
	// 同步核公开引用是否仍可见且当前
	// (POST /v1/publications:validate)
	ValidatePublications(ctx context.Context, request ValidatePublicationsRequestObject) (ValidatePublicationsResponseObject, error)
	// 读取资源引用源持久提交决定
	// (GET /v1/reference-decisions/{sourceOperationId})
	ReadReferenceDecision(ctx context.Context, request ReadReferenceDecisionRequestObject) (ReadReferenceDecisionResponseObject, error)
	// 向资源库列出哪些文档引用文件
	// (GET /v1/resource-references)
	ListResourceReferences(ctx context.Context, request ListResourceReferencesRequestObject) (ListResourceReferencesResponseObject, error)
	// 受控读取已完成域快照归档
	// (GET /v1/snapshots/{snapshotId}/archive)
	ReadSnapshotArchive(ctx context.Context, request ReadSnapshotArchiveRequestObject) (ReadSnapshotArchiveResponseObject, error)
	// 删除恢复暂存或换出的旧数据目录
	// (POST /v1/snapshots:discard)
	DiscardSnapshot(ctx context.Context, request DiscardSnapshotRequestObject) (DiscardSnapshotResponseObject, error)
	// 导出屏障水位的一致快照
	// (POST /v1/snapshots:export)
	ExportSnapshot(ctx context.Context, request ExportSnapshotRequestObject) (ExportSnapshotResponseObject, error)
	// 暂存本域恢复归档，不改active目录
	// (POST /v1/snapshots:stage)
	StageSnapshot(ctx context.Context, request StageSnapshotRequestObject) (StageSnapshotResponseObject, error)
	// 只有超管彻底删除/清空回收站
	// (POST /v1/trash:purge)
	PurgeDocuments(ctx context.Context, request PurgeDocumentsRequestObject) (PurgeDocumentsResponseObject, error)
	// 后台读取整站文档树
	// (GET /v1/tree)
	ReadDocumentTree(ctx context.Context, request ReadDocumentTreeRequestObject) (ReadDocumentTreeResponseObject, error)
	// 拖拽移动层级和顺序
	// (POST /v1/tree:move)
	MoveDocument(ctx context.Context, request MoveDocumentRequestObject) (MoveDocumentResponseObject, error)
	// 拖拽调整同级顺序
	// (POST /v1/tree:reorder)
	ReorderChildren(ctx context.Context, request ReorderChildrenRequestObject) (ReorderChildrenResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// Health operation middleware
func (sh *strictHandler) Health(w http.ResponseWriter, r *http.Request) {
	var request HealthRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.Health(ctx, request.(HealthRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "Health")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(HealthResponseObject); ok {
		if err := validResponse.VisitHealthResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

